+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+        ) {
+            match value {
+                Some(value) => (
+                    Some(value.origin.x),
+                    Some(value.origin.y),
+                    Some(value.origin.z),
+                    Some(value.x_axis.x),
+                    Some(value.x_axis.y),
+                    Some(value.x_axis.z),
+                    Some(value.y_axis.x),
+                    Some(value.y_axis.y),
+                    Some(value.y_axis.z),
+                ),
+                None => (None, None, None, None, None, None, None, None, None),
+            }
+        }
+
+        fn camera_parts(
+            value: Option<&Camera>,
+        ) -> (
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+            Option<f64>,
+        ) {
+            match value {
+                Some(value) => (
+                    Some(value.position.x),
+                    Some(value.position.y),
+                    Some(value.position.z),
+                    Some(value.target.x),
+                    Some(value.target.y),
+                    Some(value.target.z),
+                    Some(value.up.x),
+                    Some(value.up.y),
+                    Some(value.up.z),
+                    Some(value.fov),
+                ),
+                None => (None, None, None, None, None, None, None, None, None, None),
+            }
+        }
+
+        fn coordinate_from_parts(x: Option<f64>, y: Option<f64>, z: Option<f64>) -> Option<Coordinate> {
+            if x.is_none() && y.is_none() && z.is_none() {
+                return None;
+            }
+            Some(Coordinate::new(x.unwrap_or(0.0), y.unwrap_or(0.0), z.unwrap_or(0.0)))
+        }
+
+        fn location_from_parts(x: Option<f64>, y: Option<f64>) -> Option<Location> {
+            if x.is_none() && y.is_none() {
+                return None;
+            }
+            Some(Location::new(x.unwrap_or(0.0), y.unwrap_or(0.0)))
+        }
+
+        fn plane_from_parts(
+            ox: Option<f64>,
+            oy: Option<f64>,
+            oz: Option<f64>,
+            xx: Option<f64>,
+            xy: Option<f64>,
+            xz: Option<f64>,
+            yx: Option<f64>,
+            yy: Option<f64>,
+            yz: Option<f64>,
+        ) -> Option<Plane> {
+            if ox.is_none()
+                && oy.is_none()
+                && oz.is_none()
+                && xx.is_none()
+                && xy.is_none()
+                && xz.is_none()
+                && yx.is_none()
+                && yy.is_none()
+                && yz.is_none()
+            {
+                return None;
+            }
+            let mut plane = Plane::world_xy();
+            plane.origin = Coordinate::new(ox.unwrap_or(0.0), oy.unwrap_or(0.0), oz.unwrap_or(0.0));
+            plane.x_axis = Coordinate::new(xx.unwrap_or(1.0), xy.unwrap_or(0.0), xz.unwrap_or(0.0));
+            plane.y_axis = Coordinate::new(yx.unwrap_or(0.0), yy.unwrap_or(1.0), yz.unwrap_or(0.0));
+            Some(plane)
+        }
+
+        fn camera_from_parts(
+            px: Option<f64>,
+            py: Option<f64>,
+            pz: Option<f64>,
+            tx: Option<f64>,
+            ty: Option<f64>,
+            tz: Option<f64>,
+            ux: Option<f64>,
+            uy: Option<f64>,
+            uz: Option<f64>,
+            fov: Option<f64>,
+        ) -> Option<Camera> {
+            if px.is_none()
+                && py.is_none()
+                && pz.is_none()
+                && tx.is_none()
+                && ty.is_none()
+                && tz.is_none()
+                && ux.is_none()
+                && uy.is_none()
+                && uz.is_none()
+                && fov.is_none()
+            {
+                return None;
+            }
+            Some(Camera {
+                position: Coordinate::new(px.unwrap_or(0.0), py.unwrap_or(0.0), pz.unwrap_or(0.0)),
+                target: Coordinate::new(tx.unwrap_or(0.0), ty.unwrap_or(0.0), tz.unwrap_or(0.0)),
+                up: Coordinate::new(ux.unwrap_or(0.0), uy.unwrap_or(0.0), uz.unwrap_or(1.0)),
+                fov: fov.unwrap_or(45.0),
+            })
+        }
