+        fn insert_design(tx: &Transaction<'_>, kit_guid: &Guid, design: &DesignFullDto, ordinal: usize) -> Result<()> {
+            let (location_x, location_y) = location_parts(design.location.as_ref());
+            let (
+                camera_px,
