+                    ordinal as i64,
+                    design.name,
+                    design.description,
+                    design.icon,
+                    design.image,
+                    design.variant,
+                    design.view,
+                    location_x,
+                    location_y,
+                    camera_px,
+                    camera_py,
+                    camera_pz,
+                    camera_tx,
+                    camera_ty,
+                    camera_tz,
+                    camera_ux,
+                    camera_uy,
+                    camera_uz,
+                    camera_fov,
+                    design.unit,
+                    design.created,
+                    design.updated,
