+            )?;
+            for (layer_ordinal, layer) in design.layers.iter().enumerate() {
+                insert_layer(tx, &design.guid, layer, layer_ordinal)?;
+            }
+            for (piece_ordinal, piece) in design.pieces.iter().enumerate() {
