+            for (attribute_ordinal, attribute) in design.attributes.iter().enumerate() {
+                insert_attribute(
+                    tx,
+                    attribute,
+                    attribute_ordinal,
+                    ScopeRefs {
+                        design: Some(&design.guid),
+                        ..ScopeRefs::default()
+                    },
+                )?;
